#!/bin/sh
# Writes Formula/cauthy.rb for a cauthy-cli release, from its checksums.txt.
#   sh scripts/formula.sh 1.1.0
set -eu
v=$1
base=https://github.com/vennet-developers/cauthy-cli/releases/download/v$v
sums=$(curl -fsSL "$base/checksums.txt")
sha() { echo "$sums" | awk -v f="cauthy_${v}_$1.tar.gz" '$2 == f { print $1 }'; }
for p in darwin_arm64 darwin_amd64 linux_arm64 linux_amd64; do
  [ -n "$(sha $p)" ] || { echo "no checksum for $p in v$v" >&2; exit 1; }
done
cat > Formula/cauthy.rb <<RUBY
# Generated by scripts/formula.sh from cauthy-cli v$v. Do not edit.
class Cauthy < Formula
  desc "Cauthy's CLI: connect an application, check its contract, run the conformance suite"
  homepage "https://github.com/vennet-developers/cauthy-cli"
  version "$v"
  license "Apache-2.0"

  on_macos do
    on_arm do
      url "$base/cauthy_${v}_darwin_arm64.tar.gz"
      sha256 "$(sha darwin_arm64)"
    end
    on_intel do
      url "$base/cauthy_${v}_darwin_amd64.tar.gz"
      sha256 "$(sha darwin_amd64)"
    end
  end

  on_linux do
    on_arm do
      url "$base/cauthy_${v}_linux_arm64.tar.gz"
      sha256 "$(sha linux_arm64)"
    end
    on_intel do
      url "$base/cauthy_${v}_linux_amd64.tar.gz"
      sha256 "$(sha linux_amd64)"
    end
  end

  def install
    bin.install "cauthy"
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/cauthy version")
  end
end
RUBY
